corrected_code:
const express = require('express');
const router = express.Router();

router.post('/api/webauthn/hybrid/pair-device', authenticateToken, async (req, res) => {
  const { pairingSessionId, devicePublicKey } = req.body;
  const targetUserId = req.user.id;

  const session = await db.hybridPairingSessions.findOne({ sessionId: pairingSessionId, initiatorUserId: targetUserId });
  if (!session || session.status !== 'PENDING') {
    return res.status(400).json({ error: 'Invalid or expired pairing session' });
  }

  await db.userAuthenticators.insertOne({
    userId: targetUserId,
    deviceKey: devicePublicKey,
    pairedAt: new Date(),
    status: 'ACTIVE'
  });

  await db.hybridPairingSessions.updateOne({ sessionId: pairingSessionId }, { $set: { status: 'COMPLETED' } });
  return res.json({ paired: true, targetUserId });
});
